package com.bank.core;

import java.math.BigDecimal;

public class SavingsAccount extends Account { // the subclass B
    private final BigDecimal interestRate;
    public SavingsAccount(String accountId, BigDecimal balance, BigDecimal interestRate) {
        super(accountId, balance);
        this.interestRate = interestRate;
    }
    @Override
    public String kind() { return "SAVINGS"; } // true override

    // Subclass-specific method — only reachable via a SavingsAccount reference.
    public BigDecimal projectedInterest() { return balance.multiply(interestRate); }
}
