package com.bank.core;

import java.math.BigDecimal;
import java.util.logging.*;

public class UpcastDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // VALID upcast: every SavingsAccount IS-A Account.
        Account a = new SavingsAccount("SAV2001", new BigDecimal("1000000.00"),
                                       new BigDecimal("0.065"));

        // Dynamic dispatch: runtime object's override runs.
        log.info(() -> "a.kind() via Account ref → " + a.kind()); // SAVINGS

        // INVALID (compile error) — an Account is not guaranteed to be a SavingsAccount:
        //   SavingsAccount b = new Account(...);  // does not compile

        // Unguarded downcast would be risky; guard with instanceof.
        if (a instanceof SavingsAccount) {
            SavingsAccount sav = (SavingsAccount) a; // safe: object truly IS a SavingsAccount
            log.info(() -> "projectedInterest → " + sav.projectedInterest());
        }

        // A genuinely wrong downcast throws at runtime (demonstrated safely).
        Account plain = new Account("GEN0001", new BigDecimal("1000.00"));
        try {
            SavingsAccount bad = (SavingsAccount) plain; // ClassCastException
            log.info(() -> "should not reach: " + bad.kind());
        } catch (ClassCastException e) {
            log.log(Level.SEVERE, "Unguarded downcast of a plain Account failed", e);
        }
    }
}
